/* Exact primitive traces for counters, resizing, queues, monotonic stacks and binary blocks. */
'use strict';
(()=>{
const clone=x=>JSON.parse(JSON.stringify(x)),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const popcount=n=>{let k=0;while(n){k+=n%2;n=Math.floor(n/2);}return k;};
const phi=(n,C,shrink=false)=>shrink?(n>=C/2?2*n-C:C/2-n):Math.max(0,2*n-C);
function validate(raw){
const s={kind:'growth',count:9,width:5,start:0,values:[3,1,4,2,5],operations:[],factor:2,...clone(raw)};
if(!['counter','growth','shrink','thrash','queue','monotonic','multipop','blocks','migration'].includes(s.kind))throw Error('Choose a supported mathematical mechanism.');
for(const k of['count','width','start'])if(!Number.isSafeInteger(s[k]))throw Error('Count, width and initial value must be integers.');
if(s.count<0||s.count>32||s.width<2||s.width>6||s.start<0||s.start>=2**s.width)throw Error('Use count 0–32, width 2–6 and a value representable by the width.');
if(![1.5,2,3].includes(s.factor))throw Error('The growth factor must be 1.5, 2 or 3.');
if(!Array.isArray(s.values)||s.values.length>12||s.values.some(x=>!Number.isSafeInteger(x)||Math.abs(x)>99))throw Error('Provide at most twelve integer values between -99 and 99.');
if(!Array.isArray(s.operations)||s.operations.length>32||s.operations.some(o=>!o||!['push','pop','multipop','enqueue','dequeue','append'].includes(o.type)||o.value!==undefined&&(!Number.isSafeInteger(o.value)||Math.abs(o.value)>99)||o.k!==undefined&&(!Number.isSafeInteger(o.k)||o.k<0||o.k>32)))throw Error('Operation lists must contain at most 32 valid bounded operations.');
if(['shrink','thrash'].includes(s.kind)){if(s.factor!==2)throw Error('The shrink policies use doubling and halving.');s.capacity??=16;s.size??=5;if(!Number.isSafeInteger(s.capacity)||![2,4,8,16,32].includes(s.capacity)||!Number.isSafeInteger(s.size)||s.size<0||s.size>s.capacity)throw Error('Shrinking examples require a power-of-two capacity 2–32 and a legal initial size.');if(s.kind==='shrink'&&s.capacity>2&&s.size<=s.capacity/4)throw Error('Use a reachable completed state above the shrink threshold, or minimum capacity two.');}
if(s.kind==='blocks'&&s.count>16)throw Error('Sorted-block examples accept at most sixteen insertions.');return s;
}
function evaluate(raw){const s=validate(raw),states=[];let z={kind:s.kind,operation:0,actual:0,charges:0,potential:0,initialPotential:0,complete:true,local:0,action:'Initial state',why:'No operation has been executed.',records:[],capacity:1};
const emit=(action,why,extra={})=>{Object.assign(z,extra,{action,why});if(z.kind==='counter'&&z.bits)z.potential=z.bits.reduce((a,b)=>a+b,0);states.push(clone(z));};
const begin=action=>{z.operation++;z.local=0;z.complete=false;z.beforePotential=z.potential;emit(action,'The operation has started. Intermediate primitive states do not certify a completed-call charge.');};
const work=(action,why,extra={})=>{z.actual++;z.local++;emit(action,why,extra);};
const finish=why=>{z.charge=z.local+z.potential-z.beforePotential;z.charges+=z.charge;z.complete=true;emit('Complete operation '+z.operation,why);};
if(s.kind==='counter'){
z.value=s.start;z.width=s.width;z.bits=Array.from({length:s.width},(_,j)=>Math.floor(s.start/2**j)%2);z.potential=popcount(s.start);z.initialPotential=z.potential;emit('Counter initialized','Bit zero is on the right. Count only existing bit flips; wrapping creates no extra high bit.');
for(let i=0;i<s.count;i++){begin('Increment '+z.value);let j=0;while(j<s.width&&z.bits[j]===1){z.bits[j]=0;work('Clear bit '+j,'A trailing one becomes zero, releasing one popcount credit.',{cursor:j});j++;}if(j<s.width){z.bits[j]=1;work('Set bit '+j,'The first zero becomes one; lower trailing bits were cleared.',{cursor:j});}z.value=(z.value+1)%2**s.width;z.potential=z.bits.reduce((a,b)=>a+b,0);finish('Real flips plus final-minus-initial popcount certify this increment. A wrap has zero charge.');}
}else if(s.kind==='growth'||s.kind==='shrink'||s.kind==='thrash'){
let n=s.kind==='growth'?0:s.size,C=s.kind==='growth'?1:s.capacity,nextId=n;
z.records=Array.from({length:n},(_,i)=>({id:'K'+i,value:i+1}));z.capacity=C;z.potential=s.kind==='growth'?Math.max(0,(s.factor*n-C)/(s.factor-1)):phi(n,C,true);z.initialPotential=z.potential;
emit('Array initialized','A numbered storage position is fixed; a K identifier follows its record. Copies and new writes are counted separately.');
const ops=s.kind==='growth'?Array.from({length:s.count},()=>({type:'append'})):s.operations;
for(const o of ops){if(!['append','pop'].includes(o.type))throw Error('Array sequences support append and pop only.');begin(o.type+' at size '+n);if(o.type==='append'){
if(n===C){z.old=clone(z.records);z.oldCapacity=C;C=Math.ceil(s.factor*C);z.capacity=C;z.records=[];emit('Allocate new capacity '+C,'Allocation is outside this copy/write cost model; every live old record must migrate.');for(const r of z.old){z.records.push(clone(r));work('Copy '+r.id,'The new buffer receives this same record identity.',{cursor:z.records.length-1});}z.old=null;}
z.records.push({id:'K'+nextId++,value:n+1});n++;work('Write appended record','The appended record occupies the next logical position.');
}else if(n){z.records.pop();n--;work('Remove last record','The deletion occurs before checking the shrink threshold.');const threshold=s.kind==='thrash'?C/2:C/4;if(C>2&&n<=threshold){z.old=clone(z.records);z.oldCapacity=C;C/=2;z.capacity=C;z.records=[];emit('Shrink capacity to '+C,'The surviving records are copied after removal; read the stated half or quarter threshold.');for(const r of z.old){z.records.push(clone(r));work('Copy survivor '+r.id,'Only records still live after removal are copied.',{cursor:z.records.length-1});}z.old=null;}}else work('Empty pop check','There is no record to remove; the public empty check costs one.');
z.potential=s.kind==='growth'?Math.max(0,(s.factor*n-C)/(s.factor-1)):phi(n,C,true);finish(s.kind==='thrash'?'This deliberately bad half-threshold policy can have growing charges; it is a counterexample, not a constant bound.':'Use completed size and capacity to select the correct potential branch.');}
}else if(s.kind==='queue'){
z.input=[];z.output=[];emit('Queue initialized','Both arrays are shown bottom to top. The rightmost record of each row is its stack top.');let nextId=0;
for(const o of s.operations){if(!['enqueue','dequeue'].includes(o.type))throw Error('Queue sequences support enqueue and dequeue only.');if(z.input.length+z.output.length>=16&&o.type==='enqueue')throw Error('Keep at most sixteen live queue records for the compact diagram.');begin(o.type);
if(o.type==='enqueue'){z.input.push({id:'K'+nextId++,value:o.value??nextId});work('Push onto input','A new record waits behind every already queued record.');}
else{if(!z.output.length){while(z.input.length){const r=z.input.pop();z.pending=r;work('Pop input '+r.id,'The current input top is the next record moved in this reversal.');z.output.push(r);z.pending=null;work('Push output '+r.id,'Reversal exposes the oldest input record at output top only after the transfer completes.');}}if(z.output.length){const r=z.output.pop();z.returned=r;work('Return '+r.value,'Output top is the oldest remaining FIFO record.');}else work('Empty dequeue check','No record is present in either stack.');}
z.potential=2*z.input.length;finish('Each remaining input record carries two transfer credits; output records need none.');}
}else if(s.kind==='monotonic'){
z.values=s.values;z.stack=[];z.comparisons=0;emit('Monotonic stack initialized',s.equal?'Pop while top is smaller or equal; later ties replace earlier ones.':'Pop only while top is strictly smaller; equal candidates remain.');
for(let i=0;i<s.values.length;i++){begin('Process index '+i);z.current=i;while(z.stack.length){z.comparisons++;const top=z.stack.at(-1);emit('Compare top with incoming value','The declared strict or inclusive predicate determines whether this index is dominated.',{predicate:s.equal?s.values[top]<=s.values[i]:s.values[top]<s.values[i]});if(!(s.equal?s.values[top]<=s.values[i]:s.values[top]<s.values[i]))break;const removed=z.stack.pop();work('Pop index '+removed,'This index is removed once and will never reenter this stack.');}z.stack.push(i);work('Push index '+i,'The new index becomes the last candidate.');z.potential=z.stack.length;finish('Only stack modifications are charged; value comparisons have their own visible counter.');}
}else if(s.kind==='multipop'){
z.stack=[];let nextId=0;emit('Stack initialized','The row is bottom to top; multipop removes only existing records.');
for(const o of s.operations){if(!['push','pop','multipop'].includes(o.type))throw Error('Stack sequences support push, pop and multipop only.');begin(o.type);if(o.type==='push'){if(z.stack.length>=16)throw Error('Keep at most sixteen live stack records.');z.stack.push({id:'K'+nextId++,value:o.value??nextId});work('Push record','The new record creates one removal credit.');}else{const k=o.type==='pop'?1:o.k??0;for(let j=0;j<k&&z.stack.length;j++){const r=z.stack.pop();work('Remove '+r.id,'This record is consumed once.');}}z.potential=z.stack.length;finish('Element-only cost excludes dispatch checks; an empty bounded removal has zero element work.');}
}else if(s.kind==='blocks'){
z.blocks=[];emit('Sorted blocks initialized','Level j is empty or contains exactly 2 to the j records, sorted by value.');
for(let i=0;i<s.count;i++){begin('Insert value '+(i+1));let block=[i+1],j=0;work('Write singleton','A new size-one block begins the binary carry.',{pending:block});while(z.blocks[j]){const a=z.blocks[j];z.blocks[j]=null;block=[...a,...block].sort((a,b)=>a-b);for(let k=0;k<block.length;k++)work('Write merge output '+k,'Merging arrays charges every output record, unlike a constant-cost binomial link.',{pending:block,level:j+1,cursor:k});j++;}z.blocks[j]=block;z.pending=null;z.potential=0;finish('The real write total is shown directly; this model uses aggregate level counting, not a constant insertion potential.');}
}else{
const C=4;z.capacity=8;z.oldCapacity=4;z.old=Array.from({length:C},(_,i)=>({id:'K'+i,value:i+1}));z.records=Array(8).fill(null);z.boundary=0;z.size=4;z.potential=0;emit('Migration starts from a full four-record buffer','Allocation is excluded. Reads below the boundary use new storage; uncopied old positions use old storage.');
for(let i=0;i<4;i++){begin('Append with one scheduled copy');z.records[z.size]={id:'K'+z.size,value:z.size+1};z.size++;work('Write new suffix record','New suffix indices exist only in the new buffer.');z.records[z.boundary]=clone(z.old[z.boundary]);z.boundary++;work('Advance migration boundary','Exactly one old record moves; its new location becomes authoritative.');finish('Two primitive writes per append complete the four old copies by the time the new buffer is full.');}z.old=null;emit('Migration complete','The old buffer may now be released. This append-only schedule does not model arbitrary concurrent mutations.');}
return {spec:s,states,result:clone(z)};
}
const txt=(x,y,t,cls='am-prose')=>'<text x="'+x+'" y="'+y+'" class="'+cls+'">'+esc(t)+'</text>';
const rect=(id,x,y,w,h,value,fill='#edf5f7')=>'<g'+(id?' data-entity="'+esc(id)+'"':'')+'><rect x="'+x+'" y="'+y+'" width="'+w+'" height="'+h+'" rx="7" fill="'+fill+'" stroke="#8aadb9"/>'+txt(x+w/2,y+h/2+5,value,'am-value')+'</g>';
function row(a,y,capacity,label,ids=true){let out=txt(30,y-16,capacity>16?label.split('·')[0]+'· '+capacity+' slots; first sixteen shown':label),cols=Math.min(16,capacity),w=Math.min(72,688/Math.max(1,cols));for(let i=0;i<cols;i++){out+=txt(30+i*w+(w-6)/2,y+58,i,'am-index');const r=a[i];out+=rect(r&&ids?r.id:null,30+i*w,y,w-6,38,r?.value??r??'–');if(r&&ids&&r.id)out+=txt(30+i*w+(w-6)/2,y+80,r.id,'am-id');}return out;}
function drawing(z){let out='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 760 400" role="img" aria-label="'+esc(z.action)+'">';
out+=txt(30,28,z.action);
if(z.kind==='counter'){const w=84,start=700-z.width*w;for(let j=z.width-1;j>=0;j--){const x=start+(z.width-1-j)*w;out+=txt(x+33,75,'bit '+j,'am-index');out+=rect('bit'+j,x,92,66,56,z.bits[j],z.cursor===j?'#f8e3aa':'#edf5f7');}out+=txt(30,203,'Completed numeric value: '+z.value+' · potential (popcount): '+z.potential);out+=txt(30,242,'Highlighted bit is the latest real flip, not an interpolated arithmetic value.');}
else if(['growth','shrink','thrash','migration'].includes(z.kind)){if(z.old){const old=z.old.map((r,i)=>i<(z.kind==='migration'?z.boundary:z.records.length)?null:r);out+=row(old,83,z.oldCapacity,'Old buffer · source records not yet authoritative in new buffer');out+=row(z.records,208,z.capacity,'New buffer · fixed slot indices, stable record identifiers');}else{out+=row(z.records,106,z.capacity,'Active buffer · logical size '+z.records.filter(Boolean).length);out+=txt(30,233,'Capacity '+z.capacity+' · last completed potential '+Number(z.potential.toFixed(4)));}if(z.kind==='migration')out+=txt(30,307,z.boundary===4?'Migration complete: all live indices use new storage.':'Read routing: new below '+z.boundary+'; old from '+z.boundary+' through 3; new suffix from 4.');else out+=txt(30,307,z.kind==='thrash'?'Half threshold intentionally demonstrates rebuild oscillation.':'Resize timing: grow before append; shrink after removal.');}
else if(z.kind==='queue'){out+=row(z.input,100,Math.max(1,z.input.length),'Input stack · bottom → top');out+=row(z.output,220,Math.max(1,z.output.length),'Output stack · bottom → top');if(z.pending)out+=rect(z.pending.id,706,173,44,38,z.pending.value,'#f8e3aa');out+=txt(30,307,'Returned: '+(z.returned?.value??'none')+' · FIFO reads output right-to-left, then input left-to-right.');}
else if(z.kind==='monotonic'){out+=row(z.values.map(value=>({value})),90,z.values.length,'Input values · incoming index '+(z.current??'none'),false);out+=row(z.stack.map(i=>({id:'I'+i,value:z.values[i]})),215,Math.max(1,z.stack.length),'Candidate stack · bottom → top');out+=txt(30,307,'Value comparisons '+z.comparisons+' · last pop predicate '+(z.predicate??'not tested'));}
else if(z.kind==='multipop'){out+=row(z.stack,124,Math.max(1,z.stack.length),'Stack · bottom → top');out+=txt(30,265,'Remaining records '+z.stack.length+' · one future-removal credit per record.');}
else{for(let j=0;j<Math.max(1,z.blocks.length);j++){const b=z.blocks[j];out+=rect(null,30+j*136,80,120,55,'size '+2**j);out+=txt(30+j*136,166,b?(b.length<=4?b.join(', '):b[0]+' … '+b.at(-1)):'empty','am-block');}if(z.pending)out+=txt(30,235,'Carry block: ['+z.pending.slice(0,8).join(', ')+(z.pending.length>8?' …':'')+']');out+=txt(30,283,'Each merge output write is counted; levels are distinct from fixed array slots.');}
out+=txt(30,354,'Actual total '+z.actual+' · charge total '+Number(z.charges.toFixed(4))+' · initial potential '+z.initialPotential,'am-math');out+=txt(30,383,'Operation '+z.operation+' · local work '+z.local+' · complete '+z.complete,'am-math');return out+'</svg>';}
function makeModel(id,title,raw){const e=evaluate(raw);return {id,title,invariant:'Numbered labels beneath cells identify current storage positions; K and I labels identify records and original indices. Read the declared primitive model. Only completed operation checkpoints use the endpoint potential to certify a charge; intermediate states show real primitive work.',spec:e.spec,result:e.result,frames:e.states.map((z,i)=>({label:z.action,caption:z.why,svg:drawing(z),duration:800,index:i,formula:z.complete?'T = A + \\Phi_0 - \\Phi_N':'',snapshot:{inputs:e.spec,state:z,result:i===e.states.length-1?e.result:null},teaching:{currentState:z.action,operation:'Amortized mechanism: '+z.action,why:z.why,reading:z.kind==='counter'?'Bits are labeled by their positional index. Yellow marks the latest bit flip.':z.kind==='queue'?'Each row is one real stack; its right edge is the top. Reversal happens only when output is empty.':z.kind==='blocks'?'These are sorted blocks of exponentially increasing sizes, not one shared array.':'Storage indices stay fixed while record identifiers follow moves. Read size, capacity and the actual primitive ledger.',checks:[{mathHtml:'Public operation is complete',result:String(z.complete)},{mathHtml:'Exact telescoping identity applies at this completed endpoint',result:z.complete?String(Math.abs(z.actual-(z.charges+z.initialPotential-z.potential))<1e-8):'Not evaluated during a partial operation'}]}}))};}
if(typeof module!=='undefined')module.exports={validate,evaluate,makeModel,phi,popcount};if(typeof document==='undefined')return;
function mount(host,m){const c=document.createElement('div');c.className='am-controls';c.innerHTML='<button data-reset>Restart</button><button data-prev>Previous</button><button data-play>Play</button><button data-next>Next</button><label>Speed<select data-speed></select></label><label>Step<input type="range" data-seek min="0" value="0"></label>';host.querySelector('.am-stage').before(c);for(const cls of['am-caption','am-formula','am-print'])if(!host.querySelector('.'+cls)){const el=document.createElement('div');el.className=cls;host.append(el);}return AdvancedSimulations.mount(host,m,{topic:'a_amortized',prefix:'am',retainDrawing:true});}
async function boot(){const data=await(await fetch('a_amortized-models.json')).json();globalThis.AmortizedPlayers=[];for(const h of document.querySelectorAll('[data-am-model]')){const m=data.models.find(x=>x.id===h.dataset.amModel);if(!m)throw Error('Missing exact-cost model');AmortizedPlayers.push(mount(h,m));}const form=document.querySelector('#am-form'),out=document.querySelector('#am-output'),error=document.querySelector('#am-error');let active;form.addEventListener('submit',ev=>{ev.preventDefault();try{const kind=form.elements.kind.value;if(!form.elements.count.value.trim()||!form.elements.width.value.trim()||!form.elements.start.value.trim())throw Error('Specify each numeric parameter.');const raw={kind,count:Number(form.elements.count.value),width:Number(form.elements.width.value),start:Number(form.elements.start.value),factor:Number(form.elements.factor.value)};if(kind==='monotonic'){const p=form.elements.values.value.split(',');if(p.some(x=>!x.trim()))throw Error('Every comma-separated value must be present.');raw.values=p.map(x=>Number(x.trim()));raw.equal=form.elements.equal.checked;}const m=makeModel('editable-amortized','Your exact '+kind+' experiment',raw);active?.dispose();out.innerHTML='<section class="am-model"><h3>'+esc(m.title)+'</h3><div class="am-stage"></div></section><h3>Exact final state</h3><pre>'+esc(JSON.stringify(m.result,null,2))+'</pre>';active=mount(out.firstChild,m);globalThis.AmortizedLab=active;error.textContent='';}catch(e){error.textContent=e.message;}});form.dispatchEvent(new Event('submit',{cancelable:true}));}boot().catch(e=>{document.querySelector('#am-error').textContent=e.message;throw e;});
})();
